// Writes generated/registry.json. The file it writes is generated output: the
// decision record says why it is not maintained by hand.
import { writeFile } from 'node:fs/promises';

const registry = {
  _note: 'Generated by npm run build. Never hand-edited; the build overwrites it.',
  widgets: ['alpha', 'beta'],
  generatorVersion: 3,
};

await writeFile(new URL('../generated/registry.json', import.meta.url), `${JSON.stringify(registry, null, 2)}\n`);
